@import url('https://fonts.googleapis.com/css2?family=Readex+Pro:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

/* Twitch DNA — glitch purple dark, live energy */
.theme-twitch-dna {
  --bg: oklch(0.165 0.004 285.9);
  --surface: oklch(0.210 0.006 285.9);
  --surface-2: oklch(0.271 0.011 285.6);
  --fg: oklch(0.953 0.003 286.3);
  --fg-muted: oklch(0.751 0.016 286.0);
  --accent: oklch(0.591 0.255 296.1);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.749 0.155 301.3);
  --line: oklch(1 0 0 / 14%);
  --success: oklch(0.615 0.143 147.4);
  --warning: oklch(0.788 0.151 74.9);
  --danger: oklch(0.615 0.190 27.8);
  --radius: 0.375rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.5rem;
  --radius-pill: 9999px;
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Readex Pro", sans-serif;
  --font-body: "Readex Pro", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0em;
  --label-transform: none;
  --label-tracking: 0.04em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-twitch-dna h1,
.theme-twitch-dna h2,
.theme-twitch-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-twitch-dna { --font-ui: var(--font-display); }
.theme-twitch-dna h1 { font-weight: 700; }
.theme-twitch-dna h2::before { content: "⏺ "; color: var(--danger); font-size: 0.6em; vertical-align: middle; }

/* depth */
.theme-twitch-dna button { transition: transform 100ms ease-out, box-shadow 100ms ease-out; }
.theme-twitch-dna button:hover { transform: translate(-2px, -2px); box-shadow: 3px 3px 0 0 var(--accent); }
.theme-twitch-dna button:active { transform: translate(0, 0); box-shadow: 0 0 0 0 var(--accent); }
.theme-twitch-dna thead th { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 0.1em; color: var(--fg-muted); border-bottom: 2px solid var(--accent); }
.theme-twitch-dna tbody td { border-bottom: 1px solid var(--line); }
.theme-twitch-dna tbody tr:hover td { background: color-mix(in oklab, var(--accent) 10%, transparent); }
.theme-twitch-dna a { color: var(--accent-2); font-weight: 600; text-decoration: none; }
.theme-twitch-dna a:hover { color: oklch(0.850 0.110 301.0); text-decoration: underline; text-underline-offset: 3px; }
.theme-twitch-dna ::selection { background: var(--accent); color: var(--accent-fg); }
.theme-twitch-dna input:focus-visible, .theme-twitch-dna select:focus-visible, .theme-twitch-dna textarea:focus-visible { outline: none; border-color: var(--accent); box-shadow: 0 0 0 2px var(--accent); }
.theme-twitch-dna kbd { font-family: var(--font-mono); font-size: 0.75em; padding: 0.1em 0.45em; border-radius: var(--radius-sm); background: color-mix(in oklab, var(--accent) 25%, var(--surface-2)); border: 1px solid color-mix(in oklab, var(--accent) 50%, transparent); color: oklch(0.900 0.070 300.0); }
.theme-twitch-dna ::-webkit-scrollbar { width: 10px; height: 10px; }
.theme-twitch-dna ::-webkit-scrollbar-track { background: var(--surface); }
.theme-twitch-dna ::-webkit-scrollbar-thumb { background: color-mix(in oklab, var(--accent) 40%, var(--surface-2)); border-radius: 999px; }
.theme-twitch-dna .label-caps { color: var(--accent-2); font-weight: 700; letter-spacing: 0.08em; }
.theme-twitch-dna .themed-border { border-color: color-mix(in oklab, var(--accent) 50%, var(--line)); box-shadow: 4px 4px 0 0 color-mix(in oklab, var(--accent) 35%, transparent); }

/* alt mode: streamer light — ice-grey studio, same 9146FF purple */
.theme-twitch-dna.alt-mode {
  --bg: oklch(0.98 0.004 285.9);
  --surface: oklch(0.955 0.004 285.9);
  --surface-2: oklch(0.92 0.004 285.9);
  --fg: oklch(0.17 0.005 270);
  --fg-muted: oklch(0.46 0.01 270);
  --accent-2: oklch(0.480 0.220 296.0);
  --line: oklch(0.87 0.005 270);
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
}
.theme-twitch-dna.alt-mode a { color: oklch(0.480 0.220 296.0); }
.theme-twitch-dna.alt-mode a:hover { color: oklch(0.400 0.200 296.0); }
.theme-twitch-dna.alt-mode kbd { background: color-mix(in oklab, var(--accent) 12%, var(--surface)); color: oklch(0.420 0.210 296.0); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-display);
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }
